const D = { energy: .62, harmonics: 9, morph: .5, speed: 1, density: .6, scale: 1, lanes: 3, hue: 8, x: .5, y: .5, style: 'spectral', seed: 0, alpha: 100 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const u = Math.min(width, height);
const wu = u / 520;
const Nh = Math.max(1, Math.min(18, Math.round(P.harmonics)));
const Lanes = Math.max(1, Math.min(4, Math.round(P.lanes)));
const cycles = 1.0 + P.scale * 1.55;
const SN = Math.max(120, Math.min(240, Math.round(cycles * Nh * 2.4)));
const av = P.alpha / 100;
const style = P.style;

// ---- seed-dependent per-harmonic / per-lane structure (rebuild on change) ----
const hkey = P.seed + '|' + Nh + '|' + Lanes;
if (S.hkey !== hkey) {
  S.hkey = hkey;
  const fr = i => { const s = Math.sin(i * 127.1 + P.seed * 311.7) * 43758.5453; return s - Math.floor(s); };
  S.rate = []; S.phz = []; S.dir = []; S.lanePh = []; S.detune = [];
  for (let l = 0; l < Lanes; l++) { S.lanePh[l] = fr(l * 7 + 3) * 6.283; S.detune[l] = 0.92 + fr(l * 7 + 5) * 0.2; }
  for (let k = 1; k <= Nh; k++) { S.rate[k] = 0.15 + fr(k * 3 + 1) * 0.5; S.phz[k] = fr(k * 3 + 2) * 6.283; S.dir[k] = fr(k * 3 + 9) < 0.5 ? -1 : 1; }
}

// ---- section / time drivers (motion floor from K.t; audio on top) ----
const morphE = Math.max(0, Math.min(1, P.morph + 0.28 * Math.sin(K.section * 0.8 + 1) + 0.1 * Math.sin(K.t * 0.05)));
const dt = K.t * (0.15 + P.speed * 0.55);
const sc = K.t * (0.20 + P.speed * 0.60);
const hueShift = K.section * 10 + K.t * 1.2;
const ampScale = 0.70 + 0.30 * K.intensity + 0.20 * K.swell;
const audioGlow = A.rms * 0.5 + A.bass * 0.4;

// ---- style palette ----
let gTop, gBot, grat, sumH, sumS, useGlow = true, crt = false;
if (style === 'phosphor') { gTop = [150, 30, 3]; gBot = [145, 35, 9]; grat = [130, 65, 22, 26]; sumH = 125; sumS = 85; crt = true; }
else if (style === 'amber') { gTop = [30, 42, 3]; gBot = [28, 48, 10]; grat = [33, 72, 26, 26]; sumH = 38; sumS = 92; crt = true; }
else if (style === 'neon') { gTop = [285, 55, 3]; gBot = [250, 52, 9]; grat = [300, 62, 18, 22]; sumH = 190; sumS = 12; }
else if (style === 'blueprint') { gTop = [212, 60, 50]; gBot = [214, 64, 40]; grat = [210, 78, 32, 60]; sumH = 210; sumS = 8; useGlow = false; }
else { gTop = [248, 66, 5]; gBot = [252, 56, 18]; grat = [250, 46, 27, 32]; sumH = 45; sumS = 55; } // spectral

function harmColor(k) {
  const s = Nh > 1 ? (k - 1) / (Nh - 1) : 0;
  if (style === 'phosphor') return [120 + s * 34, 90, 42 + s * 42];
  if (style === 'amber') return [30 + s * 16, 95, 46 + s * 40];
  if (style === 'neon') return [(P.hue + s * 300 + hueShift * 2 + k * 15) % 360, 100, 86];
  if (style === 'blueprint') return [195 - s * 20, 26 + s * 34, 92];
  return [(P.hue + s * 280 + hueShift + 360) % 360, 82, 70 + s * 8]; // spectral
}

// ---- ground gradient (fills frame; keeps luminance up) ----
push();
noStroke();
const GB = 46;
for (let b = 0; b < GB; b++) {
  const f = b / (GB - 1);
  fill(gTop[0] + (gBot[0] - gTop[0]) * f, gTop[1] + (gBot[1] - gTop[1]) * f, gTop[2] + (gBot[2] - gTop[2]) * f, 100 * av);
  rect(0, f * height, width + 1, height / GB + 2);
}
pop();

// ---- graticule ----
push();
stroke(grat[0], grat[1], grat[2], grat[3] * av);
strokeWeight(1);
for (let vx = 1; vx < 14; vx++) line(vx / 14 * width, 0, vx / 14 * width, height);
for (let l = 0; l < Lanes; l++) {
  const cy = (l + 0.5) / Lanes * height;
  stroke(grat[0], grat[1], grat[2], grat[3] * 1.5 * av); line(0, cy, width, cy);
  stroke(grat[0], grat[1], grat[2], grat[3] * av);
  line(0, cy - height / Lanes * 0.33, width, cy - height / Lanes * 0.33);
  line(0, cy + height / Lanes * 0.33, width, cy + height / Lanes * 0.33);
}
pop();

// ---- helper ----
function poly(xs, ys, n) { beginShape(); for (let q = 0; q < n; q++) vertex(xs[q], ys[q]); endShape(); }

push();
noFill();
strokeJoin(ROUND);
strokeCap(ROUND);
const sxArr = new Float32Array(SN), syArr = new Float32Array(SN);
const hxArr = new Float32Array(SN), hyArr = new Float32Array(SN);
const harmA = (9 + P.density * 46) * av;
const glowA = Math.min(90, (26 + P.energy * 30 + audioGlow * 60 + K.swell * 18)) * av;
const coreA = Math.min(100, (72 + P.energy * 22)) * av;

for (let l = 0; l < Lanes; l++) {
  const laneY = (l + 0.5) / Lanes * height + (P.y - 0.5) * (height / Lanes) * 0.5;
  const laneAmpPx = Math.min(height / Lanes * 0.48, height / Lanes * 0.44 * (0.35 + P.energy * 0.95) * ampScale);
  const detune = S.detune[l], lanePh = S.lanePh[l];

  // per-harmonic amplitude + phase (constant across x)
  const amp = new Float64Array(Nh + 1), phs = new Float64Array(Nh + 1);
  let sumAbs = 0;
  for (let k = 1; k <= Nh; k++) {
    const saw = 1 / k;
    const sq = (k % 2 === 1) ? 1 / k : 0;
    const base = saw * (1 - morphE) + sq * morphE;
    const wob = 0.6 + 0.4 * Math.sin(K.t * S.rate[k] * (0.5 + P.speed * 0.5) + S.phz[k] + lanePh);
    const fftv = (A.fft && A.fft.length) ? (A.fft[Math.min(A.fft.length - 1, (k * 3) | 0)] / 255) : 0;
    const a = base * wob * (1 + fftv * 1.3);
    amp[k] = a; sumAbs += Math.abs(a);
    phs[k] = S.dir[k] * dt * (0.6 + k * 0.03) + S.phz[k] + lanePh + P.x * 6.283;
  }
  const norm = laneAmpPx / Math.max(0.02, sumAbs);
  const twoPi = 6.28318;

  // faint individual harmonics (spectral / style-colored)
  for (let k = 1; k <= Nh; k++) {
    const hc = harmColor(k);
    const ak = amp[k] * norm, pk = phs[k];
    for (let xi = 0; xi < SN; xi++) {
      const uu = xi / (SN - 1);
      const theta = uu * cycles * twoPi * detune + sc;
      hxArr[xi] = uu * width;
      hyArr[xi] = laneY - ak * Math.sin(k * theta + pk);
    }
    stroke(hc[0], hc[1], hc[2], harmA);
    strokeWeight((0.9 + 0.4 / k) * wu);
    poly(hxArr, hyArr, SN);
  }

  // composite sum polyline
  for (let xi = 0; xi < SN; xi++) {
    const uu = xi / (SN - 1);
    const theta = uu * cycles * twoPi * detune + sc;
    let ssum = 0;
    for (let k = 1; k <= Nh; k++) ssum += amp[k] * Math.sin(k * theta + phs[k]);
    sxArr[xi] = uu * width;
    syArr[xi] = laneY - ssum * norm;
  }
  if (useGlow) {
    blendMode(ADD);
    stroke(sumH, sumS * 0.55, 100, glowA * 0.5); strokeWeight((5.5 + P.energy * 3) * wu); poly(sxArr, syArr, SN);
    stroke(sumH, sumS, 100, glowA); strokeWeight(2.6 * wu); poly(sxArr, syArr, SN);
    blendMode(BLEND);
    stroke(sumH, sumS * 0.35, 100, coreA); strokeWeight(1.5 * wu); poly(sxArr, syArr, SN);
  } else {
    stroke(sumH, sumS, 100, coreA); strokeWeight(2.0 * wu); poly(sxArr, syArr, SN);
  }
}
pop();

// ---- CRT scanlines (phosphor / amber only) ----
if (crt) {
  push();
  stroke(0, 0, 0, 20 * av);
  strokeWeight(1);
  for (let yy = 0; yy < height; yy += 3) line(0, yy, width, yy);
  pop();
}
blendMode(BLEND);
